// POST { e_sorder_id: "S2737687.0001", to_emails: ["a@b.com", ...],
// from_email: "rep@fairbankequipment.com" }. Same address rules as the page:
// lowercase, a-z 0-9 . _ + - before the @, a dotted domain after it.
// The mail goes out from from_email's own mailbox, so it must be a
// Fairbank address; ProfitPad staff (@profitpad.com, testing and support)
// send from treyj@fairbankequipment.com instead (user's request, 2026-10-19),
// with that mailbox's signature. The page sends the signed-in rep's address.
const b = $input.first().json.body || {};
const bad = (error) => [{ json: { ok: false, statusCode: 400, body: { success: false, error, step: 'validate' } } }];
const m = String(b.e_sorder_id || '').trim().toUpperCase().match(/^S?(\d+)\.(\d{1,4})$/);
if (!m) return bad('Missing or invalid e_sorder_id (expected S1234567.0001).');
const EMAIL = /^[a-z0-9_+-]+(\.[a-z0-9_+-]+)*@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;
const list = (Array.isArray(b.to_emails) ? b.to_emails : String(b.to_emails || '').split(/[,;\s]+/))
  .map((e) => String(e).trim().toLowerCase()).filter(Boolean);
const to = [...new Set(list)];
if (!to.length) return bad('Add at least one email address.');
if (to.length > 20) return bad('Send to 20 addresses or fewer.');
const wrong = to.filter((e) => !EMAIL.test(e));
if (wrong.length) return bad('Not a valid email address: ' + wrong.join(', '));
const requested = String(b.from_email || '').trim().toLowerCase();
if (!EMAIL.test(requested)) return bad('Missing or invalid from_email.');
const from = /@profitpad\.com$/.test(requested) ? 'treyj@fairbankequipment.com' : requested;
if (!/@fairbankequipment\.com$/.test(from)) return bad('The quote can only be sent from a fairbankequipment.com mailbox.');
return [{ json: { ok: true, e_sorder_id: 'S' + m[1] + '.' + m[2].padStart(4, '0'), to, from, requested_by: requested } }];

const v = $('Validate').first().json;
const d = $input.first().json || {};
const stop = (statusCode, body) => [{ json: { ok: false, statusCode, body } }];
if (d.error) return stop(502, { success: false, error: 'HubSpot deal lookup failed: ' + d.error + ' ' + JSON.stringify(d.message || '').substring(0, 300), step: 'getDeal' });
if (d.objectFound === false || !d.id) return stop(404, { success: false, error: 'No HubSpot deal for ' + v.e_sorder_id + ' yet.', step: 'getDeal' });
const ids = [...new Set(((((d.associations || {}).quotes) || {}).results || []).map((r) => String(r.id)).filter(Boolean))];
if (!ids.length) return stop(404, { success: false, error: 'No quote for ' + v.e_sorder_id + ' yet.', step: 'getDeal' });
return [{ json: { ok: true, dealId: String(d.id), quoteIds: ids.join(',') } }];

// The same quote View Quote shows: the newest one with a public link.
const v = $('Validate').first().json;
const r = $input.first().json || {};
const stop = (statusCode, body) => [{ json: { ok: false, statusCode, body } }];
if (r.error) return stop(502, { success: false, error: 'HubSpot quote read failed: ' + r.error, step: 'quotes' });
const q = (Array.isArray(r.results) ? r.results : [])
  .filter((x) => !x.archived && x.properties && x.properties.hs_quote_link)
  .sort((a, b) => String(b.properties.hs_createdate || '').localeCompare(String(a.properties.hs_createdate || '')))[0];
if (!q) return stop(404, { success: false, error: 'No published quote for ' + v.e_sorder_id + ' yet.', step: 'quotes' });
if (!q.properties.hs_pdf_download_link) return stop(409, { success: false, error: 'HubSpot has no PDF for this quote yet. Try again in a minute.', step: 'quotes' });
return [{ json: { ok: true, quoteId: String(q.id), link: q.properties.hs_quote_link, pdfLink: q.properties.hs_pdf_download_link } }];

// The email (the user's template, 2026-10-19): a "View your quote" button,
// the PDF attached, and the rep's signature (same layout as
// email_sig.html: name, job title, Wichita phone + mobile, Wichita address).
const v = $('Validate').first().json;
const q = $('Pick quote').first().json;
const item = $input.first();
const bin = item.binary && item.binary.data;
if (!bin || (item.json && item.json.error)) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'Could not download the quote PDF' + (item.json && item.json.error ? ': ' + item.json.error : '.'), step: 'pdf' } } }];
if (!/pdf/i.test(bin.mimeType || '') && !/\.pdf$/i.test(bin.fileName || '')) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'The quote download was not a PDF (' + (bin.mimeType || 'unknown type') + ').', step: 'pdf' } } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
// Sender: the HubSpot user with this email (users Get, idProperty email).
const u = $('HubSpot: sender').first().json || {};
const up = u.properties || u;
const local = v.from.split('@')[0];
const fullName = [up.hs_given_name, up.hs_family_name].filter(Boolean).join(' ') || local;
const jobtitle = up.hs_job_title || '';
const mobile = up.mobile_phone || '';
const phoneLine = '<b>W:</b> 316-943-2247' + (mobile ? ' | <b>M:</b> ' + esc(mobile) : '');
const addressLine = '989 W Steeple Bay Pkwy | Wichita, KS 67217';
const brandColor = '#1c3a5e';

const signatureHtml = `<table style="width:360px;border-collapse:collapse">
  <tbody>
    <tr>
      <td colspan="2" style="border-bottom:2.25pt solid rgb(1,37,150);padding:5px 10px;vertical-align:top">
        <p style="margin:0;padding:3px 0;font-family:Aptos,sans-serif;font-size:11pt"><b>${esc(fullName)}</b></p>
        ${jobtitle ? `<p style="margin:0;padding:3px 0;font-family:Aptos,sans-serif;font-size:11pt"><i>${esc(jobtitle)} – Fairbank</i></p>` : ''}
      </td>
    </tr>
    <tr>
      <td style="border-right:2.25pt solid rgb(1,37,150);padding:0 10px;vertical-align:top">
        <a href="http://www.fairbankequipment.com" target="_blank">
          <img src="https://43793456.fs1.hubspotusercontent-na1.net/hubfs/43793456/Outlook%20Signature%20Logo.png" style="max-width:65px">
        </a>
      </td>
      <td style="padding:0 8px;vertical-align:top">
        <p style="margin:0;padding-top:10px;font-family:Aptos,sans-serif;font-size:9pt"><i>${phoneLine}</i></p>
        <p style="margin:0;padding-top:3px;font-family:Aptos,sans-serif;font-size:9pt"><i>${addressLine}</i></p>
        <p style="margin:0;padding-top:3px;font-family:Aptos,sans-serif;font-size:9pt">
          <a style="color:rgb(1,37,150)" href="http://www.fairbankequipment.com" target="_blank">
            <i><u>www.fairbankequipment.com</u></i>
          </a>
        </p>
        <a href="http://www.fairbankequipment.com" target="_blank">
          <img style="padding-top:10px;max-width:250px" src="https://43793456.fs1.hubspotusercontent-na1.net/hubfs/43793456/fairbank_group_logo.png">
        </a>
      </td>
    </tr>
  </tbody>
</table>`;

const subject = 'Your Fairbank Quote is Ready';
const htmlBody = `
<div style="font-family: Arial, Helvetica, sans-serif; color: #333333; font-size: 15px; line-height: 1.6; max-width: 560px;">
  <p style="margin: 0 0 16px;">Hi there,</p>
  <p style="margin: 0 0 16px;">Thank you for requesting a quote; it's attached as a PDF. You can also view it online using the button below.</p>
  <p style="margin: 0 0 28px;">
    <a href="${esc(q.link)}" style="background-color: ${brandColor}; color: #ffffff; text-decoration: none; padding: 12px 28px; border-radius: 4px; display: inline-block; font-weight: bold;">View your quote</a>
  </p>
  <p style="margin: 0 0 24px;">Any questions? Just reply to this email and I'll be glad to help.</p>
  ${signatureHtml}
</div>`;

const fileName = 'Quote ' + v.e_sorder_id + '.pdf';
// BCC the signed-in sender so the quote lands in their Inbox, not just Sent
// Items (user's request, 2026-10-23). ProfitPad staff get it at their own
// address, not the treyj mailbox. Skipped when they are already in To.
const bcc = v.to.includes(v.requested_by) ? [] : [{ email: v.requested_by }];
return [{
  json: { ok: true, mailbox: v.from, subject, htmlBody, to: v.to.map((email) => ({ email })), bcc },
  binary: { data: Object.assign({}, bin, { fileName, fileExtension: 'pdf', mimeType: 'application/pdf' }) },
}];

const v = $('Validate').first().json;
const q = $('Pick quote').first().json;
const r = $input.first().json || {};
if (r.error) return [{ json: { ok: false, statusCode: 502, body: { success: false, error: 'Outlook could not send the email: ' + r.error + ' ' + JSON.stringify(r.message || r.description || '').substring(0, 300), step: 'sendMail' } } }];
return [{ json: { ok: true, statusCode: 200, body: { success: true, e_sorder_id: v.e_sorder_id, quote_id: q.quoteId, quote_link: q.link, from: v.from, sent_to: v.to } } }];
